#include "lems/data/dataset.hpp"
#include <iostream>
int main(int argc,char**argv){try{if(argc!=2){std::cerr<<"usage: lems-data-inspect CONFIG.yaml\n";return 2;}auto d=lems::data::open_dataset(lems::data::load_config(argv[1]));std::cout<<"cameras: "<<d->cameras().size()<<"\n";for(const auto&c:d->cameras())std::cout<<"  "<<c.name<<" K=["<<c.K[0]<<", 0, "<<c.K[2]<<"; 0, "<<c.K[4]<<", "<<c.K[5]<<"; 0, 0, 1]\n";if(d->stereo_calibration())std::cout<<"stereo baseline: "<<d->stereo_calibration()->baseline<<" m\n";auto it=d->iterate();size_t n=0,disparities=0,masks=0;while(auto s=it->next()){for(const auto&f:s->frames){disparities+=f.metadata.disparity_path.has_value();masks+=f.metadata.occlusion_mask_path.has_value();}if(n<3)std::cout<<"set "<<s->index<<": "<<s->frames.size()<<" cameras @ "<<s->timestamp_ns<<" ns\n";++n;}std::cout<<"total frame sets: "<<n<<"\ndisparity maps: "<<disparities<<"\nocclusion masks: "<<masks<<"\n";}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<"\n";return 1;}}
